#!/usr/bin/env python3
"""
Dual-Transport UI Shell - Binary Schema & Code Generator
Generates authoritative C++ headers and TypeScript definitions with compile-time assertions.
"""

import os
import sys

def generate_cpp_header(output_path: str):
    header_content = """// ==============================================================================
// AUTOMATICALLY GENERATED FILE - DO NOT EDIT MANUALLY!
// Generated by tools/generate_binary_schema.py
// Lucid Engine Dual-Transport UI Shell Binary Contract v1.1
// ==============================================================================

#pragma once

#include <atomic>
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <type_traits>

namespace engine::network {

inline constexpr uint32_t kProtocolMagic      = 0x55495348; // "UISH" (0x55, 0x49, 0x53, 0x48)
inline constexpr uint32_t kProtocolVersion    = 1;
inline constexpr uint32_t kRingSlotCount      = 32;
inline constexpr size_t   kMaxBufferedAmount  = 512;        // 512B threshold for WebSocket backpressure

// Frame types for 8-byte network frame header
enum BinaryFrameType : uint8_t {
    FRAME_TYPE_FULL_SNAPSHOT = 0x01, // C++ -> UI (overwritable)
    FRAME_TYPE_BLOCK_DELTA   = 0x02, // C++ -> UI (overwritable)
    FRAME_TYPE_RPC_COMMAND   = 0x10, // UI -> C++ (reliable MPSC queue)
    FRAME_TYPE_RPC_ACK       = 0x11, // C++ -> UI (reliable queue)
};

// State flags embedded in TelemetrySnapshot
enum TelemetryStateFlags : uint32_t {
    STATE_FLAG_NONE         = 0,
    STATE_FLAG_SIMULATING   = 1 << 0,
    STATE_FLAG_PAUSED       = 1 << 1,
    STATE_FLAG_AUDIO_MUTED  = 1 << 2,
    STATE_FLAG_VR_ACTIVE    = 1 << 3,
    STATE_FLAG_NET_ACTIVE   = 1 << 4,
};

#pragma pack(push, 8)
struct alignas(8) TelemetrySnapshot {
    uint32_t magic;            // Offset 0:  kProtocolMagic
    uint32_t version;          // Offset 4:  kProtocolVersion
    uint64_t seq_head;         // Offset 8:  Sequence counter written BEFORE metrics
    float    cpu_frame_ms;     // Offset 16: Continuous domain CPU frame time in ms
    float    output_level_db;  // Offset 20: Master audio output level in dB
    uint32_t state_flags;      // Offset 24: TelemetryStateFlags bitfield
    uint32_t active_entities;  // Offset 28: Count of active entities in world
    uint64_t seq_tail;         // Offset 32: Sequence counter closing consistent frame
};
#pragma pack(pop)

static_assert(std::is_trivially_copyable_v<TelemetrySnapshot>, "TelemetrySnapshot must be trivially copyable");
static_assert(sizeof(TelemetrySnapshot) == 40, "TelemetrySnapshot size must be exactly 40 bytes");
static_assert(alignof(TelemetrySnapshot) == 8, "TelemetrySnapshot alignment must be 8 bytes");
static_assert(offsetof(TelemetrySnapshot, magic) == 0, "magic offset mismatch");
static_assert(offsetof(TelemetrySnapshot, version) == 4, "version offset mismatch");
static_assert(offsetof(TelemetrySnapshot, seq_head) == 8, "seq_head offset mismatch");
static_assert(offsetof(TelemetrySnapshot, cpu_frame_ms) == 16, "cpu_frame_ms offset mismatch");
static_assert(offsetof(TelemetrySnapshot, output_level_db) == 20, "output_level_db offset mismatch");
static_assert(offsetof(TelemetrySnapshot, state_flags) == 24, "state_flags offset mismatch");
static_assert(offsetof(TelemetrySnapshot, active_entities) == 28, "active_entities offset mismatch");
static_assert(offsetof(TelemetrySnapshot, seq_tail) == 32, "seq_tail offset mismatch");

#pragma pack(push, 1)
struct NetworkFrameHeader {
    uint8_t  type;          // Offset 0: BinaryFrameType (0x01, 0x02, 0x10, 0x11)
    uint8_t  flags;         // Offset 1: Reserved flags
    uint16_t stream_id;     // Offset 2..3: Stream / Sub-channel ID
    uint32_t payload_len;   // Offset 4..7: Length of aligned payload following header
};
#pragma pack(pop)

static_assert(sizeof(NetworkFrameHeader) == 8, "NetworkFrameHeader must be exactly 8 bytes");

struct alignas(64) SharedStateRing {
    std::atomic<uint32_t> active_slot;              // Offset 0: Last committed ring slot (0..31)
    uint32_t              pad[15];                  // Offset 4..63: CPU cache line isolation (64B)
    TelemetrySnapshot     slots[kRingSlotCount];    // Offset 64..1343: 32 slots of 40 bytes
};

static_assert(sizeof(SharedStateRing) == 64 + kRingSlotCount * 40, "SharedStateRing size must be 1344 bytes");
static_assert(alignof(SharedStateRing) == 64, "SharedStateRing alignment must be 64 bytes");
static_assert(offsetof(SharedStateRing, slots) == 64, "slots offset must be at 64 bytes");

// RPC Command message for MPSC queue
struct alignas(8) RpcCommandMessage {
    uint32_t command_id;
    uint32_t request_id;
    uint32_t payload_len;
    uint32_t reserved;
    uint8_t  payload[256];
};

static_assert(sizeof(RpcCommandMessage) == 16 + 256, "RpcCommandMessage size mismatch");

// Seqlock write helper function (C++ Engine main loop)
inline void writeTelemetrySnapshot(SharedStateRing& ring, uint64_t& seqCounter, float cpuMs, float audioDb, uint32_t flags, uint32_t entities) {
    uint32_t currentSlot = ring.active_slot.load(std::memory_order_relaxed);
    uint32_t nextSlot = (currentSlot + 1) % kRingSlotCount;
    TelemetrySnapshot& slot = ring.slots[nextSlot];

    uint64_t seq = ++seqCounter;
    slot.magic = kProtocolMagic;
    slot.version = kProtocolVersion;
    slot.seq_head = seq;
    slot.cpu_frame_ms = cpuMs;
    slot.output_level_db = audioDb;
    slot.state_flags = flags;
    slot.active_entities = entities;

    std::atomic_thread_fence(std::memory_order_release);
    slot.seq_tail = seq;
    ring.active_slot.store(nextSlot, std::memory_order_release);
}

// Seqlock read helper function (tail -> memcpy -> head on private buffer)
inline bool readTelemetrySnapshotSeqlock(const SharedStateRing& ring, TelemetrySnapshot& outSnapshot, uint64_t& lastSeq) {
    uint32_t slotIdx = ring.active_slot.load(std::memory_order_acquire) % kRingSlotCount;
    const volatile TelemetrySnapshot& slot = ring.slots[slotIdx];

    // 1. Read tail sequence with acquire fence
    uint64_t tail = slot.seq_tail;
    std::atomic_thread_fence(std::memory_order_acquire);

    // 2. Copy 40 bytes into private thread buffer
    std::memcpy(&outSnapshot, const_cast<const void*>(static_cast<const volatile void*>(&slot)), sizeof(TelemetrySnapshot));
    std::atomic_thread_fence(std::memory_order_acquire);

    // 3. Read head sequence
    uint64_t head = slot.seq_head;

    // 4. Verify consistency and ensure freshness
    if (tail == head && tail != 0 && tail > lastSeq && outSnapshot.magic == kProtocolMagic && outSnapshot.version == kProtocolVersion) {
        lastSeq = tail;
        return true;
    }
    return false;
}

} // namespace engine::network
"""
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(header_content)
    print(f"[OK] Generated C++ Header: {output_path}")

def generate_typescript_module(output_path: str):
    ts_content = """// ==============================================================================
// AUTOMATICALLY GENERATED FILE - DO NOT EDIT MANUALLY!
// Generated by tools/generate_binary_schema.py
// Lucid Engine Dual-Transport UI Shell Binary Contract v1.1
// ==============================================================================

export const PROTOCOL_MAGIC = 0x55495348; // "UISH"
export const PROTOCOL_VERSION = 1;
export const RING_SLOT_COUNT = 32;
export const MAX_BUFFERED_AMOUNT = 512; // 512 bytes threshold for WebSocket backpressure

// Frame types for 8-byte network frame header
export const BinaryFrameType = {
  FULL_SNAPSHOT: 0x01, // C++ -> UI (overwritable)
  BLOCK_DELTA:   0x02, // C++ -> UI (overwritable)
  RPC_COMMAND:   0x10, // UI -> C++ (reliable MPSC queue)
  RPC_ACK:       0x11, // C++ -> UI (reliable queue)
} as const;
export type BinaryFrameType = typeof BinaryFrameType[keyof typeof BinaryFrameType];

// State flags
export const TelemetryStateFlags = {
  NONE:         0,
  SIMULATING:   1 << 0,
  PAUSED:       1 << 1,
  AUDIO_MUTED:  1 << 2,
  VR_ACTIVE:    1 << 3,
  NET_ACTIVE:   1 << 4,
} as const;
export type TelemetryStateFlags = typeof TelemetryStateFlags[keyof typeof TelemetryStateFlags];

// Byte offsets for TelemetrySnapshot (Total: 40 bytes, alignas 8)
export const OFF_MAGIC            = 0;  // uint32
export const OFF_VERSION          = 4;  // uint32
export const OFF_SEQ_HEAD         = 8;  // uint64 (BigInt)
export const OFF_CPU_FRAME_MS     = 16; // float32
export const OFF_OUTPUT_LEVEL_DB  = 20; // float32
export const OFF_STATE_FLAGS      = 24; // uint32
export const OFF_ACTIVE_ENTITIES  = 28; // uint32
export const OFF_SEQ_TAIL         = 32; // uint64 (BigInt)
export const SNAPSHOT_SIZE        = 40;

// Byte offsets for SharedStateRing (Total: 1344 bytes, alignas 64)
export const OFF_RING_ACTIVE_SLOT = 0;  // uint32
export const RING_HEADER_SIZE     = 64; // 64 bytes cache-line pad
export const SHARED_RING_TOTAL_SIZE = RING_HEADER_SIZE + RING_SLOT_COUNT * SNAPSHOT_SIZE; // 1344

// Network Frame Header (Total: 8 bytes)
export const NET_OFF_TYPE         = 0; // uint8
export const NET_OFF_FLAGS        = 1; // uint8
export const NET_OFF_STREAM_ID    = 2; // uint16
export const NET_OFF_PAYLOAD_LEN  = 4; // uint32
export const NET_HEADER_SIZE      = 8;

export interface TelemetrySnapshotData {
  magic: number;
  version: number;
  seqHead: bigint;
  cpuFrameMs: number;
  outputLevelDb: number;
  stateFlags: number;
  activeEntities: number;
  seqTail: bigint;
}

/**
 * High-performance zero-allocation parser for TelemetrySnapshot.
 * Directly reads flat binary ArrayBuffers and DataViews without JS heap garbage.
 */
export class TelemetrySnapshotReader {
  /**
   * Safely reads a consistent TelemetrySnapshot from a 40-byte slice using
   * the seqlock verification protocol (tail -> copy -> head).
   */
  public static tryReadConsistent(
    sourceView: DataView,
    sourceByteOffset: number,
    out: TelemetrySnapshotData,
    lastSeq: bigint
  ): boolean {
    if (sourceView.byteLength < sourceByteOffset + SNAPSHOT_SIZE) {
      return false;
    }

    // 1. Read tail sequence first (Little Endian)
    const tail = sourceView.getBigUint64(sourceByteOffset + OFF_SEQ_TAIL, true);
    if (tail === 0n || tail <= lastSeq) {
      return false;
    }

    // 2. Read magic and version
    const magic = sourceView.getUint32(sourceByteOffset + OFF_MAGIC, true);
    const version = sourceView.getUint32(sourceByteOffset + OFF_VERSION, true);
    if (magic !== PROTOCOL_MAGIC || version !== PROTOCOL_VERSION) {
      return false;
    }

    // 3. Read metrics
    const cpuFrameMs = sourceView.getFloat32(sourceByteOffset + OFF_CPU_FRAME_MS, true);
    const outputLevelDb = sourceView.getFloat32(sourceByteOffset + OFF_OUTPUT_LEVEL_DB, true);
    const stateFlags = sourceView.getUint32(sourceByteOffset + OFF_STATE_FLAGS, true);
    const activeEntities = sourceView.getUint32(sourceByteOffset + OFF_ACTIVE_ENTITIES, true);

    // 4. Read head sequence
    const head = sourceView.getBigUint64(sourceByteOffset + OFF_SEQ_HEAD, true);

    // 5. Verify consistency: tail must match head
    if (tail !== head) {
      return false; // Tearing detected, writer was active during read
    }

    // All fields consistent! Write to preallocated output object
    out.magic = magic;
    out.version = version;
    out.seqHead = head;
    out.cpuFrameMs = cpuFrameMs;
    out.outputLevelDb = outputLevelDb;
    out.stateFlags = stateFlags;
    out.activeEntities = activeEntities;
    out.seqTail = tail;

    return true;
  }
}
"""
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(ts_content)
    print(f"[OK] Generated TypeScript Module: {output_path}")

def main():
    root_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    cpp_path = os.path.join(root_dir, "engine", "include", "network", "DualTransportContracts.hpp")
    ts_path = os.path.join(root_dir, "src", "transport", "TelemetrySnapshot.ts")

    print("[SCHEMA] Generating Dual-Transport UI Shell Binary Contracts...")
    generate_cpp_header(cpp_path)
    generate_typescript_module(ts_path)
    print("[SCHEMA] Generation completed successfully!")

if __name__ == "__main__":
    main()
